/**
 * Offline file mesh. Pages already on disk. A query never opens the live web.
 */
import { readdirSync, readFileSync, statSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { reviewFile } from "../hyb011-denylist.mjs";
import { buildIndex, searchIndex } from "../../../../preview/src/lib/tessera/offline-index.ts";

const SKIP_DIR = new Set(["node_modules", ".git"]);

export function gitbookRoot() {
  return resolve(dirname(fileURLToPath(import.meta.url)), "../../../../archive/from-gitbook");
}

export function loadGitbookPages(root = gitbookRoot()) {
  const pages = [];
  function walk(dir) {
    for (const name of readdirSync(dir)) {
      if (SKIP_DIR.has(name)) continue;
      const abs = join(dir, name);
      const rel = relative(root, abs);
      if (!reviewFile(rel).allowed) continue;
      const info = statSync(abs);
      if (info.isDirectory()) walk(abs);
      else if (name.endsWith(".md")) {
        pages.push({ path: rel, text: readFileSync(abs, "utf8").slice(0, 2048) });
      }
    }
  }
  walk(root);
  return pages;
}

export function queryFileMesh(query, root = gitbookRoot()) {
  const pages = loadGitbookPages(root);
  const index = buildIndex(pages);
  const found = searchIndex(index, query, 20);
  return { ...found, count: index.pages.length };
}

import { spawnSync } from "node:child_process";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

export const DESK_MEM_LIMIT_MB = 32;

const PROBE = `
import net from "node:net";
import v8 from "node:v8";
if (process.env.SANDBOX_NETWORK === "deny") {
  const refused = () => {
    throw new Error("network denied");
  };
  net.connect = refused;
  net.createConnection = refused;
}
let networkDenied = false;
try {
  net.connect({ host: "127.0.0.1", port: 9 });
} catch (err) {
  networkDenied = String(err && err.message).includes("network denied");
}
process.stdout.write(JSON.stringify({
  networkDenied,
  memLimitMb: Number(process.env.SANDBOX_MEM_MB),
  heapLimit: v8.getHeapStatistics().heap_size_limit,
}));
`;

/** One desk probe: network stays denied and the heap flag is applied. */
export function runDeskProbe() {
  const dir = mkdtempSync(join(tmpdir(), "tessera-desk-"));
  const file = join(dir, "probe.mjs");
  writeFileSync(file, PROBE);
  try {
    const result = spawnSync(process.execPath, [`--max-old-space-size=${DESK_MEM_LIMIT_MB}`, file], {
      env: {
        PATH: process.env.PATH ?? "",
        SANDBOX_NETWORK: "deny",
        SANDBOX_MEM_MB: String(DESK_MEM_LIMIT_MB),
      },
      encoding: "utf8",
    });
    if (result.status !== 0) {
      throw new Error(result.stderr || "desk sandbox probe failed");
    }
    return JSON.parse(result.stdout);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

/**
 * Offices, desks, and built objects for the studio floor.
 * Grown from the task graph, worker events, and the build log.
 */

export function plateName(id) {
  if (id === "tessera") return "Tessera";
  if (id === "worker") return "Worker";
  const text = String(id);
  return text.slice(0, 1).toUpperCase() + text.slice(1);
}

export function readBuildLog(markdown) {
  const rows = [];
  for (const line of String(markdown).split("\n")) {
    const match = line.match(/^\|\s*\d+\s*\|\s*(V2-\d+)\s*\|[^|]*\|\s*([^|]+?)\s*\|/);
    if (!match) continue;
    rows.push({ id: match[1], title: match[2].trim() });
  }
  return rows;
}

function ownerId(task, desks) {
  const ids = new Set(desks.map((desk) => desk.id));
  if (/^Plan:/.test(task.title) && ids.has("tessera")) return "tessera";
  if (ids.has("worker")) return "worker";
  return desks[0]?.id ?? "tessera";
}

/** One office per desk. Done work and build-log rows add objects and rooms. */
export function buildWorld({ desks = [], tasks = [], events = [], log = [] } = {}) {
  const offices = desks.map((desk, index) => ({
    id: desk.id,
    name: plateName(desk.id),
    role: desk.role,
    x: index * 7,
    z: 0,
    lamp: desk.lamp === "busy" ? "busy" : "idle",
    walking: false,
    pieces: ["desk", "nameplate", "status-light"],
    artifacts: [],
  }));
  const byId = new Map(offices.map((office) => [office.id, office]));

  for (const task of tasks) {
    if (task.status !== "done") continue;
    const office = byId.get(ownerId(task, desks));
    if (!office) continue;
    office.artifacts.push({ id: task.id, kind: "book", title: task.title });
  }

  for (const event of events) {
    if (event.name !== "tool.write" && event.name !== "tool.read") continue;
    const office = byId.get("worker") ?? offices[0];
    if (!office) continue;
    office.walking = true;
    office.lamp = "busy";
    if (event.name === "tool.write") {
      office.artifacts.push({
        id: `${event.taskId}:${event.detail || "note"}`,
        kind: "page",
        title: event.detail || event.taskId,
      });
    }
  }

  for (const office of offices) {
    if (office.role === "worker" && tasks.some((task) => task.status === "running")) {
      office.walking = true;
      office.lamp = "busy";
    }
  }

  const rooms = [];
  for (let i = 0; i < log.length; i += 5) {
    const slice = log.slice(i, i + 5);
    rooms.push({
      id: `bay-${rooms.length + 1}`,
      title: slice[0].id,
      count: slice.length,
      x: rooms.length * 6,
      z: 8,
    });
  }

  return { offices, rooms };
}

/**
 * HYB-011 route and file denylist.
 * Refuses wallet, payment, vault, and 1T paths on the v2 surface.
 * Clean-room gate. It does not delete existing files or rewrite history.
 */

const REFUSED_SEGMENT =
  /^(?:1t|vault|wallets?|payments?|checkout|stripe|mining|nft|defi|mev|hashcat|captcha|antidetect)$/i;

const EMBEDDED_REFUSED = /(?:vault|wallet|payment|1t)/i;

function decodePart(value) {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
}

function segmentsOf(value) {
  return decodePart(String(value ?? ""))
    .replace(/\\/g, "/")
    .split(/[?#]/, 1)[0]
    .split("/")
    .filter((part) => part.length > 0 && part !== "." && part !== "..");
}

function segmentRefused(segment) {
  if (REFUSED_SEGMENT.test(segment)) return segment.toLowerCase();
  if (/(?:^|[^a-z0-9])1t(?:[^a-z0-9]|$)/i.test(segment)) return "1t";
  if (/vault/i.test(segment)) return "vault";
  if (/wallets?/i.test(segment)) return "wallet";
  if (/payments?/i.test(segment)) return "payment";
  return null;
}

export function reviewPath(value) {
  const segments = segmentsOf(value);
  for (const segment of segments) {
    const hit = segmentRefused(segment);
    if (hit) {
      return { allowed: false, status: 403, reason: "hyb-011-denied", match: hit };
    }
  }
  const query = String(value ?? "").includes("?")
    ? decodePart(String(value).slice(String(value).indexOf("?") + 1))
    : "";
  if (query) {
    for (const piece of query.split(/[&/=]/)) {
      const hit = segmentRefused(piece);
      if (hit) {
        return { allowed: false, status: 403, reason: "hyb-011-denied", match: hit };
      }
    }
  }
  return { allowed: true, status: 200, reason: "ok", match: null };
}

export function reviewRequest({ url = "/", method = "GET" } = {}) {
  const decision = reviewPath(url);
  return { ...decision, method: String(method || "GET").toUpperCase() };
}

export function reviewFile(filePath) {
  const decision = reviewPath(filePath);
  if (!decision.allowed) return decision;
  const base = segmentsOf(filePath).at(-1) ?? "";
  if (EMBEDDED_REFUSED.test(base) && segmentRefused(base)) {
    return { allowed: false, status: 403, reason: "hyb-011-denied", match: segmentRefused(base) };
  }
  return decision;
}

