function readSocketFrame(socket) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    const onData = (buf) => {
      chunks.push(buf);
      const data = Buffer.concat(chunks);
      if (data.length < 2) return;
      const short = data[1] & 0x7f;
      const start = short === 126 ? 4 : 2;
      const size = short === 126 ? data.readUInt16BE(2) : short;
      if (data.length < start + size) return;
      socket.off("data", onData);
      resolve(data.subarray(start, start + size).toString());
    };
    socket.on("data", onData);
    socket.on("error", reject);
  });
}

