        `<li><strong>${escapeHtml(bounty.title)}</strong> · ${bounty.reward} GitAI credits · ${escapeHtml(bounty.status)} · ${escapeHtml(bounty.posterHandle)}<br>${escapeHtml(bounty.brief)}</li>`,
    )

