+const studioSpec = await (await fetch("http://127.0.0.1:4173/gitai/api/openapi.json")).json();
+check("openapi", spec.openapi === "3.1.0" && studioSpec.openapi === "3.1.0" && spec.paths["/api/live"]);
+
+const health = await (await fetch("http://127.0.0.1:4173/gitai/api/health")).json();
+check("studio health", health.service === "gitai" && health.ok === true);
+
+const starred = await fetch("http://127.0.0.1:4173/gitai/api/stars", {
+  method: "POST",
+  headers: { "content-type": "application/json", "x-gitai-handle": "Jules" },
+  body: JSON.stringify({ projectId: mesh.id }),
+});
+const starBody = await starred.json();
+const afterApi = await (await fetch("http://127.0.0.1:4183/api/view")).json();
+const apiStars = afterApi.projects.find((project) => project.name === "mesh-note").stars;
+check("api star through studio proxy", starred.status === 200 && apiStars === directStars + (starBody.starred ? 1 : -1), `status ${starred.status} stars ${apiStars}`);
+
+const mobile = await browser.newPage({ viewport: { width: 390, height: 844 } });
+await mobile.goto("http://127.0.0.1:4183/", { waitUntil: "domcontentloaded" });
+await mobile.screenshot({ path: "/tmp/gitai-mobile.png", fullPage: false });
+const box = await mobile.locator(".layout").boundingBox();
+check("mobile layout stacks", box && box.width < 400, JSON.stringify(box));
+
+await browser.close();
+if (failures.length) {
+  console.error(failures.join("\n"));
+  process.exit(1);
